def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Hypervolume-based selection
    obj_values = np.array([obj for _, obj in archive])
    reference_point = np.max(obj_values, axis=0)
    hypervolumes = []
    for i in range(len(archive)):
        dominated = False
        for j in range(len(archive)):
            if i != j and (obj_values[j][0] >= obj_values[i][0] and obj_values[j][1] >= obj_values[i][1]) and (obj_values[j][0] > obj_values[i][0] or obj_values[j][1] > obj_values[i][1]):
                dominated = True
                break
        if not dominated:
            hv = (reference_point[0] - obj_values[i][0]) * (reference_point[1] - obj_values[i][1])
            hypervolumes.append((i, hv))

    if hypervolumes:
        selected_idx = max(hypervolumes, key=lambda x: x[1])[0]
    else:
        selected_idx = random.randint(0, len(archive)-1)

    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst[base_solution == 1])

    # Phase 1: Value-balanced flips
    value_balance = value1_lst / (value2_lst + 1e-8)
    sorted_indices = np.argsort(value_balance)
    for i in sorted_indices:
        if random.random() < 0.6:
            if new_solution[i] == 1:
                if current_weight - weight_lst[i] >= 0:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]
            else:
                if current_weight + weight_lst[i] <= capacity and (value_balance[i] > 1.2 or random.random() < 0.3):
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Phase 2: Objective-specific swaps
    if random.random() < 0.5:
        in_items = np.where(new_solution == 1)[0]
        out_items = np.where(new_solution == 0)[0]

        if len(in_items) > 0 and len(out_items) > 0:
            # Select best candidate to add
            add_candidates = out_items
            add_scores = (value1_lst[add_candidates] + value2_lst[add_candidates]) / weight_lst[add_candidates]
            best_add = add_candidates[np.argmax(add_scores)]

            # Select worst candidate to remove
            remove_scores = (value1_lst[in_items] + value2_lst[in_items]) / weight_lst[in_items]
            worst_remove = in_items[np.argmin(remove_scores)]

            # Perform swap if feasible
            if (current_weight - weight_lst[worst_remove] + weight_lst[best_add]) <= capacity:
                new_solution[worst_remove] = 0
                new_solution[best_add] = 1
                current_weight = current_weight - weight_lst[worst_remove] + weight_lst[best_add]

    # Phase 3: Diversity-preserving perturbation
    if random.random() < 0.3:
        diversity_factor = 0.2 + 0.8 * (1 - len(archive)/100)
        for i in range(len(weight_lst)):
            if random.random() < diversity_factor:
                if new_solution[i] == 1:
                    if current_weight - weight_lst[i] >= 0:
                        new_solution[i] = 0
                        current_weight -= weight_lst[i]
                else:
                    if current_weight + weight_lst[i] <= capacity:
                        new_solution[i] = 1
                        current_weight += weight_lst[i]

    # Final feasibility check
    total_weight = np.sum(weight_lst[new_solution == 1])
    if total_weight > capacity:
        included_items = np.where(new_solution == 1)[0]
        ratios = (value1_lst[included_items] + value2_lst[included_items]) / weight_lst[included_items]
        sorted_indices = included_items[np.argsort(ratios)]
        excess = total_weight - capacity
        for i in sorted_indices:
            if excess <= 0:
                break
            excess -= weight_lst[i]
            new_solution[i] = 0

    return new_solution

