def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Cluster solutions based on hamming distance
    solutions = [sol for sol, _ in archive]
    n = len(solutions)
    clusters = {}
    for i in range(n):
        min_dist = float('inf')
        best_cluster = -1
        for cluster_id in clusters:
            for sol in clusters[cluster_id]:
                dist = np.sum(solutions[i] != sol)
                if dist < min_dist:
                    min_dist = dist
                    best_cluster = cluster_id
        if min_dist > len(weight_lst) * 0.3 or best_cluster == -1:
            clusters[len(clusters)] = [solutions[i]]
        else:
            clusters[best_cluster].append(solutions[i])

    # Select from least populated cluster
    selected_cluster = min(clusters.keys(), key=lambda x: len(clusters[x]))
    base_solution = random.choice(clusters[selected_cluster]).copy()
    new_solution = base_solution.copy()

    # Calculate marginal contributions
    marginal1 = value1_lst / (weight_lst + 1e-6)
    marginal2 = value2_lst / (weight_lst + 1e-6)
    combined_marginal = marginal1 + marginal2

    # Adaptive item selection
    current_weight = sum(weight_lst * new_solution)
    remaining_capacity = capacity - current_weight

    # Phase 1: Add high marginal items
    candidates = np.where(new_solution == 0)[0]
    if len(candidates) > 0:
        sorted_candidates = candidates[np.argsort(combined_marginal[candidates])[::-1]]
        for item in sorted_candidates:
            if weight_lst[item] <= remaining_capacity:
                new_solution[item] = 1
                remaining_capacity -= weight_lst[item]
                break

    # Phase 2: Remove low marginal items if over capacity
    if remaining_capacity < 0:
        selected_items = np.where(new_solution == 1)[0]
        sorted_selected = selected_items[np.argsort(combined_marginal[selected_items])]
        for item in sorted_selected:
            new_solution[item] = 0
            remaining_capacity += weight_lst[item]
            if remaining_capacity >= 0:
                break

    # Dynamic perturbation
    perturbation_rate = min(0.5, 0.1 + 0.4 * (1 - sum(weight_lst * new_solution) / capacity))
    for i in range(len(weight_lst)):
        if np.random.rand() < perturbation_rate:
            if new_solution[i] == 1:
                if sum(weight_lst * new_solution) - weight_lst[i] >= 0:
                    new_solution[i] = 0
            else:
                if sum(weight_lst * new_solution) + weight_lst[i] <= capacity:
                    new_solution[i] = 1

    # Large-scale perturbation every 5 iterations (simulated)
    if random.random() < 0.2:
        num_flips = min(5, len(weight_lst))
        flip_indices = random.sample(range(len(weight_lst)), num_flips)
        for i in flip_indices:
            if new_solution[i] == 1:
                if sum(weight_lst * new_solution) - weight_lst[i] >= 0:
                    new_solution[i] = 0
            else:
                if sum(weight_lst * new_solution) + weight_lst[i] <= capacity:
                    new_solution[i] = 1

    return new_solution

