    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst[base_solution == 1])

    # Calculate objective correlation
    included = np.where(base_solution == 1)[0]
    if len(included) > 0:
        corr = np.corrcoef(value1_lst[included], value2_lst[included])[0,1]
    else:
        corr = 0

    # Adaptive local search
    flip_prob = 0.5 + 0.3 * (1 - abs(corr))  # Higher probability for low correlation

    # Marginal-gain flip
    for i in range(len(weight_lst)):
        if np.random.rand() < flip_prob:
            if base_solution[i] == 1:
                # Check if removing improves both objectives
                if (current_weight - weight_lst[i]) >= 0:
                    new_solution[i] = 0
            else:
                # Check if adding improves both objectives
                if (current_weight + weight_lst[i]) <= capacity:
                    new_solution[i] = 1

    # Feasibility enforcement
    total_weight = np.sum(weight_lst[new_solution == 1])
    if total_weight > capacity:
        excess = total_weight - capacity
        included_items = np.where(new_solution == 1)[0]

        # Weighted removal based on both objectives
        removal_weights = (value1_lst[included_items] * 0.6 + value2_lst[included_items] * 0.4) / weight_lst[included_items]
        sorted_indices = included_items[np.argsort(removal_weights)]

        for i in sorted_indices:
            if excess <= 0:
                break
            excess -= weight_lst[i]
            new_solution[i] = 0

    return new_solution
